/* ---------- сворачиваемые группы (стекло-стиль, spring-раскрытие) ---------- */
function coll(title, bodyHtml, opts = {}) {
  return `<div class="coll ${opts.open === false ? '' : 'open'}">
    <button class="coll-head" type="button">
      ${opts.icon ? `<span class="ch-ic">${ic(opts.icon)}</span>` : ''}
      <span class="ch-t">${title}</span>
      ${opts.count != null ? `<span class="ch-cnt">${opts.count}</span>` : ''}
      <span class="chev">${ic(I.chev, 2)}</span>
    </button>
    <div class="coll-body"><div class="coll-inner">${bodyHtml}</div></div>
  </div>`;
}
document.addEventListener('click', (e) => {
  const h = e.target.closest('.coll-head');
  if (h) h.parentElement.classList.toggle('open');
});

/* конвертация валют (source→display) по живым курсам (open.er-api.com, per USD). */
const FX_PER_USD = { USD: 1, EUR: 0.92, AED: 3.6725, THB: 36, IDR: 16300, RUB: 92, GBP: 0.79, TRY: 34 };
let FXRATES = null;   /* {CCY: units per 1 USD} — подтягивается из /api/fx, кэш на сервере 24ч */
async function ensureFx() { if (FXRATES) return; try { const r = await api.get('/fx'); if (r && r.rates) FXRATES = r.rates; } catch (_) {} }
const CUR_LIST = ['USD', 'EUR', 'AED', 'THB', 'IDR', 'RUB'];   /* валюты недвижки: доллар/евро/дирхам/бат/рупия(Бали)/рубль */
function fxConv(amount, from, to) {
  from = from || 'USD'; to = to || from; if (from === to) return amount || 0;
  const per = FXRATES || FX_PER_USD;
  const rf = per[from] || FX_PER_USD[from] || 1, rt = per[to] || FX_PER_USD[to] || 1;
  return (amount || 0) / rf * rt;
}
function curSym(c) { return ({ USD: '$', EUR: '€', AED: 'dh ', THB: '฿', IDR: 'Rp ', RUB: '₽', GBP: '£', TRY: '₺' })[c] || (c + ' '); }

/* диапазон дат аналитики рекламы (пресеты + свой период) → {from,to} и query-string */
const AD_RANGE_PRESETS = [['today', 'Сегодня'], ['yesterday', 'Вчера'], ['7d', '7 дней'], ['30d', '30 дней'], ['month', 'Этот месяц'], ['all', 'Всё']];
function adRangeDates() {
  const r = PAGE_STATE.adRange || { preset: '30d' };   /* дефолт — последние 30 дней (посуточно, как в кабинете) */
  const ymd = (dt) => dt.toISOString().slice(0, 10);
  const today = new Date(); const t = ymd(today); const daysAgo = (n) => ymd(new Date(Date.now() - n * 864e5));
  switch (r.preset) {
    case 'today': return { from: t, to: t };
    case 'yesterday': return { from: daysAgo(1), to: daysAgo(1) };
    case '7d': return { from: daysAgo(6), to: t };
    case '30d': return { from: daysAgo(29), to: t };
    case 'month': return { from: ymd(new Date(today.getFullYear(), today.getMonth(), 1)), to: t };
    case 'custom': return { from: r.from || '', to: r.to || '' };
    default: return { from: '', to: '' };
  }
}
function adRangeQS() { const { from, to } = adRangeDates(); const p = []; if (from) p.push('from=' + from); if (to) p.push('to=' + to); return p.length ? ('?' + p.join('&')) : ''; }

/* ---------- «?»-подсказки: объяснялки не занимают экран, живут в поповере ---------- */
const HINTS = {};
function hint(id, title, items) {
  HINTS[id] = { title, items };
  return `<button class="hint-q" type="button" data-hint="${id}" aria-label="Как это работает">?</button>`;
}
function closeHint() { const p = document.querySelector('.hint-pop'); if (p) p.remove(); }
document.addEventListener('click', (e) => {
  const q = e.target.closest('.hint-q');
  const open = document.querySelector('.hint-pop');
  if (open && (!q || open.dataset.for === q.dataset.hint)) { open.remove(); if (q) return; }
  else if (open) open.remove();
  if (!q) return;
  const h = HINTS[q.dataset.hint];
  if (!h) return;
  const pop = document.createElement('div');
  pop.className = 'hint-pop';
  pop.dataset.for = q.dataset.hint;
  pop.innerHTML = `<div class="hp-t">${h.title}</div>` + h.items.map(([t, d]) => `<div class="hp-row"><b>${t}</b><span>${d}</span></div>`).join('');
  document.body.appendChild(pop);
  const r = q.getBoundingClientRect();
  const w = Math.min(330, window.innerWidth - 16);
  pop.style.width = w + 'px';
  pop.style.left = Math.max(8, Math.min(r.left - 8, window.innerWidth - w - 8)) + 'px';
  pop.style.top = (r.bottom + 8) + 'px';
  requestAnimationFrame(() => {
    const pr = pop.getBoundingClientRect();
    if (pr.bottom > window.innerHeight - 8) pop.style.top = Math.max(8, r.top - pr.height - 8) + 'px';
    pop.classList.add('show');
  });
});
window.addEventListener('scroll', (e) => { if (!e.target.closest?.('.hint-pop')) closeHint(); }, true);

/* ═══ ГАЙД-ЦЕНТР: красивые пошаговые инструкции под каждый функционал ═══
   Расширяемо: добавляй ключ в GUIDES и вызывай openGuide('ключ'). Рендерится премиум-модалкой. */
/* Telegram-гайд: живые телефон-мокапы (рендерятся как чёткие «скриншоты» флоу) */
const GUIDES = (typeof window !== 'undefined' && window.LUMEN_GUIDES) ? window.LUMEN_GUIDES : {};  /* данные гайдов вынесены в guides-data.js — единый источник для in-CRM и публичного /help */
/* Центр инструкций: грид всех гайдов. Вызов: openGuideCenter() */
function openGuideCenter() {
  /* порядок = категории публичного справочника (window.LUMEN_HELP), с фолбэком */
  const cats = (window.LUMEN_HELP && window.LUMEN_HELP.CATEGORIES) || null;
  const order = cats ? cats.reduce((a, c) => a.concat(c.guides), []) : ['tgsetup', 'botpanel', 'wanumbers', 'wacloud', 'tgchannel', 'telephony', 'waagent', 'leads', 'chains', 'calendar', 'mediaplan', 'docs'];
  const cards = order.filter(k => GUIDES[k]).map(k => { const g = GUIDES[k];
    return `<div class="gdc-card" data-guide="${k}" role="button" tabindex="0">
      <span class="gdc-ic">${ic(I[g.icon] || I.doc)}</span>
      <span class="gdc-tx"><b>${esc(g.title)}</b><i>${esc(g.tagline)}</i></span>
      <button type="button" class="gdc-link" data-copy="${k}" title="Скопировать публичную ссылку — отправьте клиенту" aria-label="Скопировать ссылку">${ic(I.link, 1.9)}</button>
      <span class="gdc-go">${ic(I.arrow, 2)}</span>
    </div>`;
  }).join('');
  const body = `<div class="gdc-top"><span>Эти инструкции доступны публично — жмите ${ic(I.link, 1.7)} на карточке, чтобы скопировать ссылку и отправить клиенту.</span><a class="gdc-pub" href="/help" target="_blank" rel="noopener">Открыть справочник ${ic(I.arrow, 2)}</a></div><div class="gdc-grid">${cards}</div>`;
  const m = modal({ title: 'Инструкции', sub: 'Пошаговые гайды по функциям Lumen', body, wide: true, actions: [{ label: 'Закрыть' }] });
  const root = m || document;
  root.querySelectorAll('.gdc-card').forEach(b => {
    b.addEventListener('click', () => openGuide(b.dataset.guide));
    b.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openGuide(b.dataset.guide); } });
  });
  root.querySelectorAll('.gdc-link').forEach(btn => btn.addEventListener('click', e => {
    e.stopPropagation();
    const url = location.origin + '/help/' + btn.dataset.copy;
    const ok = () => { btn.classList.add('ok'); setTimeout(() => btn.classList.remove('ok'), 1500); try { if (window.toast) window.toast('Ссылка скопирована', url, true); } catch (_) {} };
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(url).then(ok, () => prompt('Скопируйте ссылку:', url)); else prompt('Скопируйте ссылку:', url);
  }));
}
window.openGuideCenter = openGuideCenter;
function openGuide(id) {
  const g = GUIDES[id]; if (!g) return;
  const pubUrl = location.origin + '/help/' + id;
  const stepCard = (s, i) => `<div class="gd-step"><span class="gd-n">${i + 1}</span><div class="gd-tx"><b>${s[0]}</b><span>${s[1]}</span></div></div>`;
  const secBlock = (sec) => `<div class="gd-sec"><div class="gd-sec-h">${esc(sec.badge)}</div>${sec.steps.map(stepCard).join('')}${sec.shot ? `<div class="gd-shot2">${sec.shot}</div>` : ''}</div>`;
  const body = `<div class="gd">
    <div class="gd-sharebar"><span>${ic(I.doc, 1.8)}Публичная ссылка на эту инструкцию</span><button type="button" class="gd-share" data-url="${esc(pubUrl)}">${ic(I.copy || I.link || I.doc, 1.8)}<b>Скопировать ссылку</b></button></div>
    <div class="gd-intro">${g.intro}</div>
    ${g.diagram || ''}
    ${(g.sections || []).map(secBlock).join('')}
    ${g.img ? `<div class="gd-shot"><img src="${g.img}" alt="" onerror="this.parentNode.style.display='none'"><span>Поле для ссылки — в карточке брокера</span></div>` : ''}
    ${g.outro ? `<div class="gd-outro">${ic(I.spark, 2)}<span>${g.outro}</span></div>` : ''}
  </div>`;
  const m = modal({ title: g.title, sub: g.tagline, body, wide: true, actions: [{ label: 'Понятно' }] });
  const sb = (m || document).querySelector('.gd-share');
  if (sb) sb.addEventListener('click', () => {
    const u = sb.dataset.url, lbl = sb.querySelector('b');
    const done = () => { if (lbl) { lbl.textContent = 'Ссылка скопирована ✓'; setTimeout(() => { lbl.textContent = 'Скопировать ссылку'; }, 1800); } };
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(u).then(done, () => prompt('Скопируйте ссылку:', u));
    else prompt('Скопируйте ссылку:', u);
  });
}
window.openGuide = openGuide;

function plural(n, one, few, many) {
  const m = Math.abs(n) % 100, d = m % 10;
  if (m > 10 && m < 20) return many;
  if (d > 1 && d < 5) return few;
  if (d === 1) return one;
  return many;
}

