/* эстетичная цветовая градация стадий (приглушённая палитра 2026, без неона) */
const STAGE_COLORS = {
  new: '#6B7A99', touch: '#7C8FE0', dialog: '#4F7DFF', qualified: '#2FA98C',
  handover: '#8B7BD8', viewing: '#C9922E', deal: '#129B6E', sleeping: '#97A2B5', lost: '#C77B7B',
};
const STAGE_PALETTE = ['#4F7DFF', '#2FA98C', '#8B7BD8', '#C9922E', '#129B6E', '#E08A6B', '#5AAFD6', '#B07CC9'];
function stageColor(id) {
  /* через CSS-переменную --stg-<id> (тема может перекрасить донат/канбан), фолбэк = дефолт-палитра */
  if (STAGE_COLORS[id]) return `var(--stg-${id}, ${STAGE_COLORS[id]})`;
  /* кастомным стадиям — стабильный цвет из палитры по хешу id */
  let h = 0; for (let i = 0; i < String(id).length; i++) h = (h * 31 + id.charCodeAt(i)) >>> 0;
  return STAGE_PALETTE[h % STAGE_PALETTE.length];
}

/* полные названия языков для этикеток брокеров (код → человекочитаемое) */
const LANG_NAMES = { ru: 'Русский', en: 'Английский', ar: 'Арабский', id: 'Индонезийский', es: 'Испанский', de: 'Немецкий', fr: 'Французский', it: 'Итальянский', zh: 'Китайский', pt: 'Португальский', tr: 'Турецкий', fa: 'Персидский', hi: 'Хинди', uk: 'Украинский', pl: 'Польский', nl: 'Нидерландский' };
const langName = (lg) => LANG_NAMES[lg] || (lg ? lg.charAt(0).toUpperCase() + lg.slice(1) : lg);
function rebuildStages() {
  const cfg = (STATE && STATE.settings.stagesCfg) || {};
  let list = BASE_STAGES.map(st => ({ ...st, name: (cfg.names || {})[st.id] || st.name }))
    .concat((cfg.custom || []).map(c => ({ id: c.id, name: (cfg.names || {})[c.id] || c.name, icon: 'doc', custom: true })));
  if (cfg.order && cfg.order.length) {
    list.sort((a, b) => {
      const ia = cfg.order.indexOf(a.id), ib = cfg.order.indexOf(b.id);
      return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
    });
  }
  STAGES = list.filter(st => !(cfg.hidden || []).includes(st.id));
  STAGES._all = list;
}
const stageName = (id) => ((STAGES._all || STAGES).find(s => s.id === id) || {}).name || id;

/* ---------- api ---------- */
async function apiReq(method, p, b) {
  const r = await fetch('/api' + p, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: method === 'GET' ? undefined : JSON.stringify(b || {}),
  });
  if (r.status === 401) { renderLogin(); throw new Error('auth'); }
  const j = await r.json().catch(() => ({}));
  if (!r.ok) { const err = new Error((j && j.error) || ('HTTP ' + r.status)); err.status = r.status; err.code = j && j.code; err.body = j; throw err; } /* 403/404/400/402/429/500 → бросаем с текстом сервера + code/body */
  return j;
}
const api = {
  get: (p) => apiReq('GET', p),
  post: (p, b) => apiReq('POST', p, b),
  patch: (p, b) => apiReq('PATCH', p, b),
  del: (p) => apiReq('DELETE', p),
};

/* ---------- экран входа (тёмный, по бренду) ---------- */
/* ═══ i18n: инкрементальный слой. t(ru,en) — по месту вызова, без словаря ключей;
   язык из localStorage (дефолт ru), переключатель RU/EN. Непереведённое (нет en) падает на ru. ═══ */
let LANG = (function(){ try { return localStorage.getItem('lumen_lang') === 'en' ? 'en' : 'ru'; } catch(e){ return 'ru'; } })();
function t(ru, en) { return (LANG === 'en' && en != null) ? en : ru; }
window.t = t;
window.setLang = function(l) {
  LANG = (l === 'en') ? 'en' : 'ru';
  try { localStorage.setItem('lumen_lang', LANG); } catch(e){}
  try { document.documentElement.setAttribute('lang', LANG); } catch(e){}
  const ls = document.getElementById('loginScreen');
  if (ls) { ls.remove(); renderLogin(); }
  else { location.reload(); }  /* в приложении: перезагрузка — весь UI (сайдбар/заголовки/страницы) подхватит язык из localStorage */
};
/* один делегированный обработчик на все тумблеры языка (логин, настройки) */
document.addEventListener('click', (e) => { const b = e.target.closest('#langTgl [data-lang]'); if (b) { e.preventDefault(); e.stopPropagation(); window.setLang(b.dataset.lang); } });
function langToggleHTML() {
  return `<div id="langTgl" style="display:inline-flex;gap:2px;background:var(--blue-100,rgba(20,19,17,.05));border-radius:8px;padding:3px">
    <button data-lang="ru" style="border:0;border-radius:6px;padding:3px 9px;font-size:11.5px;cursor:pointer;background:${LANG==='ru'?'var(--accent,#1a1815)':'transparent'};color:${LANG==='ru'?'var(--card,#faf9f5)':'var(--ink-3,#8b8983)'};font-weight:600">RU</button>
    <button data-lang="en" style="border:0;border-radius:6px;padding:3px 9px;font-size:11.5px;cursor:pointer;background:${LANG==='en'?'var(--accent,#1a1815)':'transparent'};color:${LANG==='en'?'var(--card,#faf9f5)':'var(--ink-3,#8b8983)'};font-weight:600">EN</button>
  </div>`;
}
/* ═══ Авто-перевод контента: словарь RU→EN + проход по text-нодам/плейсхолдерам/тайтлам.
   Покрывает ВСЕ страницы одним механизмом (вызывается после каждого рендера при LANG='en'),
   без правки тысяч мест. Совпадение — по ПОЛНОМУ тексту ноды (trim), поэтому «5 лидов» с числом
   не тронется (такие смешанные строки добиваем через t() у источника). Идемпотентно. ═══ */
