    $('#tabLogin').style.color = m === 'login' ? 'var(--card)' : 'var(--ink-2)';
    $('#tabReg').style.background = m === 'register' ? 'var(--accent)' : 'transparent';
    $('#tabReg').style.color = m === 'register' ? 'var(--card)' : 'var(--ink-2)';
