          const sz = ovSizes[k] || {}; const cw = w.full ? '' : (sz.w === 'full' ? ' ov-cw-full' : sz.w === 3 ? ' ov-cw-3' : sz.w === 2 ? ' ov-cw-2' : ''); const hStyle = sz.h ? ` style="--ovh:${sz.h}px"` : '';
