            <select class="gi-sel" data-payplan style="min-width:230px">
              <option value="">пресеты рынка…</option>
              ${geoMD.payments.map((pp, pi) => `<option value="${pi}">${esc(pp.label)} · ${pp.rows.map(r2 => r2.pct).join(' / ')}</option>`).join('')}
            </select>
