function waQrGuideRich() { return '<div class="glass card mb">' + coll('Инструкция: WhatsApp по QR — подробно, со скриншотами', (window.LUMEN_RICH && window.LUMEN_RICH.wanumbers ? window.LUMEN_RICH.wanumbers() : ''), { open: false, icon: I.doc }) + '</div>'; }
