  order.forEach((o, i) => { o.role = i === 0 ? 'HERO' : i <= nPri ? 'PRIMARY' : i <= nPri + nSec ? 'SECONDARY' : 'MICRO'; });
  /* 2. ШИРИНА по роли (доля boardW), occupancy-adaptive; никогда не все одинаковые */
