  res.forEach(x => { MB_Z[x.id] = x.z; if (x.soft) MB_SOFT.add(x.id); });
  await Promise.all(res.map(x => api.patch('/moodboard/' + x.id, { x: x.x, y: x.y, w: x.w, rot: x.rot }).catch(() => {})));
  await renderMoodboard(root, opts);
